// ServerInterface represents all server handlers.
type ServerInterface interface {
	// DisconnectAIProvider Remove the tenant's AI provider configuration
	// (DELETE /integrations/ai)
	DisconnectAIProvider(c *gin.Context)
	// GetAIConnection Get the tenant's configured AI provider (for procurement document parsing), if any
	// (GET /integrations/ai)
	GetAIConnection(c *gin.Context)
	// ConnectAIProvider Configure (or switch) the tenant's AI provider -- overwrites any existing configuration, only one is active at a time
	// (POST /integrations/ai)
	ConnectAIProvider(c *gin.Context)
	// ConnectBol Connect Bol.com by pasting Retailer API client credentials -- no OAuth redirect (Bol uses client_credentials)
	// (POST /integrations/bol/connect)
	ConnectBol(c *gin.Context)
	// ListCatalog List available integration providers
	// (GET /integrations/catalog)
	ListCatalog(c *gin.Context)
	// ListConnections List this tenant's integration connections
	// (GET /integrations/connections)
	ListConnections(c *gin.Context)
	// DeleteConnection Disconnect an integration
	// (DELETE /integrations/connections/{id})
	DeleteConnection(c *gin.Context, id Id)
	// GetBolCommission Live Bol commission for this SKU's EAN at its current price (falls back to the product's CommissionOverrideBasisPoints when set, without calling Bol) -- powers the product edit page's Bol profit calculator.
	// (GET /integrations/connections/{id}/bol-commission/{productId}/{skuId})
	GetBolCommission(c *gin.Context, id Id, productId ProductId, skuId string)
	// GetBolProductOverride Get this product's Bol-specific field overrides for this connection, if any exist
	// (GET /integrations/connections/{id}/bol-overrides/{productId})
	GetBolProductOverride(c *gin.Context, id Id, productId ProductId)
	// UpsertBolProductOverride Save this product's Bol-specific field overrides for this connection
	// (PUT /integrations/connections/{id}/bol-overrides/{productId})
	UpsertBolProductOverride(c *gin.Context, id Id, productId ProductId)
	// ListExternalCategoryLinks List this connection's CommerceOS-category -> Woo-category links (auto-matched on push, or set manually here)
	// (GET /integrations/connections/{id}/category-links)
	ListExternalCategoryLinks(c *gin.Context, id Id)
	// UpsertExternalCategoryLink Create or repoint a category link for this connection
	// (POST /integrations/connections/{id}/category-links)
	UpsertExternalCategoryLink(c *gin.Context, id Id)
	// DeleteExternalCategoryLink Remove a category link
	// (DELETE /integrations/connections/{id}/category-links/{linkId})
	DeleteExternalCategoryLink(c *gin.Context, id Id, linkId LinkId)
	// FetchWooOrder Fetch and import (or update) a single WooCommerce order by its own Woo order ID/number, on demand -- for backfilling one specific known-missing order without waiting for the next scheduled sync. Runs the exact same import logic the scheduled orders sync uses, idempotent the same way (a re-fetch of an already-imported, unchanged order is a no-op).
	// (POST /integrations/connections/{id}/fetch-order)
	FetchWooOrder(c *gin.Context, id Id)
	// ImportWooProducts Enqueue a bulk import of this connection's existing WooCommerce catalog into CommerceOS. Runs in the background (see cmd/scheduler) — this returns immediately with the pending job; a notification is created when the job starts and again when it finishes or fails.
	// (POST /integrations/connections/{id}/import)
	ImportWooProducts(c *gin.Context, id Id)
	// DeleteAllImportedProducts Delete every product this connection has imported (and any category left empty by that)
	// (DELETE /integrations/connections/{id}/imported-products)
	DeleteAllImportedProducts(c *gin.Context, id Id)
	// GetProductChannelListing Get a single product's sync state for this connection (powers the product edit page's per-channel tab). 404 means the product has never been linked to this connection (not imported from it, not pushed to it).
	// (GET /integrations/connections/{id}/listings/{productId})
	GetProductChannelListing(c *gin.Context, id Id, productId ProductId)
	// ListSyncLogs The audit trail for one product's sync history on this connection — every push/import/stock attempt, what changed, when, and whether it succeeded. Newest first.
	// (GET /integrations/connections/{id}/listings/{productId}/sync-logs)
	ListSyncLogs(c *gin.Context, id Id, productId ProductId)
	// PushProductToWoo Push a single-SKU CommerceOS product to this connection's WooCommerce store as a new product
	// (POST /integrations/connections/{id}/push-product)
	PushProductToWoo(c *gin.Context, id Id)
	// PushProductToBol Push a CommerceOS product to this Bol connection as one offer per non-bulk-pool SKU
	// (POST /integrations/connections/{id}/push-product-bol)
	PushProductToBol(c *gin.Context, id Id)
	// UpdateConnectionSettings Update this connection's stored defaults (currently just default_currency)
	// (PATCH /integrations/connections/{id}/settings)
	UpdateConnectionSettings(c *gin.Context, id Id)
	// ListSyncSchedules List this connection's recurring sync schedule configuration
	// (GET /integrations/connections/{id}/sync-schedules)
	ListSyncSchedules(c *gin.Context, id Id)
	// UpsertSyncSchedules Bulk-save this connection's sync schedule rows (one per entity type + direction)
	// (PUT /integrations/connections/{id}/sync-schedules)
	UpsertSyncSchedules(c *gin.Context, id Id)
	// TestConnection Probe a connection's stored credentials against the real provider
	// (POST /integrations/connections/{id}/test)
	TestConnection(c *gin.Context, id Id)
	// SetWebhookSecret (Re)generate this connection's webhook-signature secret. Returns the PLAINTEXT secret exactly once -- paste it into the provider's webhook admin UI right away, it can't be retrieved again after this response. Re-running this rotates the secret; the old value stops verifying immediately.
	// (POST /integrations/connections/{id}/webhook-secret)
	SetWebhookSecret(c *gin.Context, id Id)
	// ListWooCategories List the categories configured in this connection's live WooCommerce store (read-only, not persisted)
	// (GET /integrations/connections/{id}/woo-categories)
	ListWooCategories(c *gin.Context, id Id)
	// ListWooTaxes List the distinct tax classes configured in this connection's live WooCommerce store (read-only, not persisted)
	// (GET /integrations/connections/{id}/woo-taxes)
	ListWooTaxes(c *gin.Context, id Id)
	// ResyncProductToChannels Force-push this product's current fields and stock to every channel it's already linked to, regardless of whether anything actually changed since the last sync -- the product page's "Resync to channels" action. Unlike retryFailedSync (which requires an existing failed sync-log entry) this always runs, and unlike the routine event-driven sync it never skips a push because the last one already reported the same values. A product with no listings is a no-op, not an error.
	// (POST /integrations/products/{productId}/resync)
	ResyncProductToChannels(c *gin.Context, productId ProductId)
	// ListSalesChannels List the tenant's sales channels
	// (GET /integrations/sales-channels)
	ListSalesChannels(c *gin.Context)
	// CreateSalesChannel Create a sales channel
	// (POST /integrations/sales-channels)
	CreateSalesChannel(c *gin.Context)
	// DeleteSalesChannel Delete a sales channel -- never delists products already pushed to the channel's connection
	// (DELETE /integrations/sales-channels/{id})
	DeleteSalesChannel(c *gin.Context, id Id)
	// UpdateSalesChannel Update a sales channel -- rename it, re-point its connection, or change its default enrollment rule. "Add all"/"add by tag"/"add by category" bulk actions are just enrollment_mode changes here, no per-product rows written.
	// (PATCH /integrations/sales-channels/{id})
	UpdateSalesChannel(c *gin.Context, id Id)
	// ListSalesChannelProducts List the tenant's products with their live-computed enrollment status for this channel
	// (GET /integrations/sales-channels/{id}/products)
	ListSalesChannelProducts(c *gin.Context, id Id, params ListSalesChannelProductsParams)
	// SetSalesChannelProductOverride Force-include ("add") or force-exclude ("remove") one product for this channel, regardless of its default enrollment rule
	// (PUT /integrations/sales-channels/{id}/products/{productId}/override)
	SetSalesChannelProductOverride(c *gin.Context, id Id, productId ProductId)
	// ListAllSyncLogs Tenant-wide sync history — every push/import/stock attempt across every product and connection, newest first. Powers the Sync History page (as opposed to the per-listing endpoint, which is scoped to one product's WooCommerce tab).
	// (GET /integrations/sync-logs)
	ListAllSyncLogs(c *gin.Context, params ListAllSyncLogsParams)
	// ListSyncLogsNeedingAttention Every listing whose most recent sync attempt failed and hasn't been dismissed, newest first — the Sync History page's "Needs attention" filter. A retry that succeeds, or a dismiss, drops the listing out of this list on its own (live query, not separate tracked state).
	// (GET /integrations/sync-logs/needing-attention)
	ListSyncLogsNeedingAttention(c *gin.Context, params ListSyncLogsNeedingAttentionParams)
	// DismissFailedSync Silence a failure that isn't worth retrying (the Woo product was deleted, a known/expected mismatch) from the "needs attention" view, without pretending it succeeded.
	// (POST /integrations/sync-logs/{id}/dismiss)
	DismissFailedSync(c *gin.Context, id Id)
	// RetryFailedSync Re-push the failed entry's product to the same connection — a full resync (not a narrow replay of just the field that failed), so the retry always leaves the listing fully caught up.
	// (POST /integrations/sync-logs/{id}/retry)
	RetryFailedSync(c *gin.Context, id Id)
	// ListWebhookFallbackEvents List webhooks that could not be published to JetStream after 3 in-request retries and were saved to the fallback table instead
	// (GET /integrations/webhook-fallback-events)
	ListWebhookFallbackEvents(c *gin.Context, params ListWebhookFallbackEventsParams)
	// AbandonWebhookFallbackEvent Mark this fallback row abandoned (discarded) -- an audit trail is kept, not a hard delete
	// (DELETE /integrations/webhook-fallback-events/{id})
	AbandonWebhookFallbackEvent(c *gin.Context, id Id)
	// RetryWebhookFallbackEvent Attempt to publish this fallback row to JetStream now; marks it republished on success
	// (POST /integrations/webhook-fallback-events/{id}/retry)
	RetryWebhookFallbackEvent(c *gin.Context, id Id)
	// ManualConnectWooCommerce Connect WooCommerce by pasting an already-generated REST API key/secret
	// (POST /integrations/woocommerce/connect/manual)
	ManualConnectWooCommerce(c *gin.Context)
	// StartWooConnect Begin the WooCommerce OAuth-style ("Application Authentication") connect flow
	// (POST /integrations/woocommerce/connect/start)
	StartWooConnect(c *gin.Context)
}

